{
  "ok": true,
  "form_version": 3,
  "applicant_type": "solo_builder",
  "questions": [
    {
      "id": "legal_name",
      "prompt": "Full legal name, as it should appear on the building access list.",
      "kind": "short",
      "required": true,
      "why": "Cloudflare needs the attendee list in advance and it FREEZES on Monday, August 24, when we hand over the final legal names for badges. A nickname at the door means no entry, and after the freeze there is no correcting it."
    },
    {
      "id": "email",
      "prompt": "Email you actually read.",
      "kind": "email",
      "required": true,
      "why": "Decision, NDA link, and day-of logistics go here. A person reads every application and the decision clears within a day of applying, so watch this address. Applications close Monday, August 24, or sooner if the seats fill."
    },
    {
      "id": "org",
      "prompt": "Company, project, or community you are coming as.",
      "kind": "short",
      "required": false
    },
    {
      "id": "handle",
      "prompt": "GitHub handle (or X / site) we can look at.",
      "kind": "short",
      "required": false,
      "why": "The fastest way for a reviewer to see that you build things."
    },
    {
      "id": "both_days",
      "prompt": "Can you attend both days, 9:00 AM to 8:30 PM PDT, Aug 26 and 27?",
      "kind": "bool",
      "required": true,
      "why": "The venue has a hard 8:30 PM out both days. Partial attendance is fine to say no to — it just changes the decision."
    },
    {
      "id": "nda_ack",
      "prompt": "Do you agree to sign the venue NDA before the event?",
      "kind": "bool",
      "required": true,
      "why": "Cloudflare sends the NDA to the confirmed roster 48 hours before doors. Unsigned means you cannot be checked in, so a no here is a rejection rather than a surprise at the door."
    },
    {
      "id": "media_ok",
      "prompt": "Are you OK being photographed and filmed for recap content?",
      "kind": "bool",
      "required": true,
      "why": "A no is honoured, not penalised. We need to know before the photographer arrives."
    },
    {
      "id": "dietary",
      "prompt": "Dietary requirements or access needs?",
      "kind": "short",
      "required": false
    },
    {
      "id": "nebius_optin",
      "prompt": "Join the Nebius mailing list? Nebius sponsors this event and gives every participant Builder Program credits.",
      "kind": "bool",
      "required": false,
      "why": "Optional and answered last for a reason: it has no bearing on the decision. Yes passes your name and email to Nebius so they can send you their developer updates. No, or leaving it blank, passes nothing."
    },
    {
      "id": "project_url",
      "prompt": "URL of the project. Live site, repo, or demo.",
      "kind": "url",
      "required": true
    },
    {
      "id": "what_it_does",
      "prompt": "What does it do, and who uses it?",
      "kind": "long",
      "required": true
    },
    {
      "id": "agent_surface_today",
      "prompt": "What is agent-native about it today? Name the surface, or say 'none yet'.",
      "kind": "long",
      "required": true
    },
    {
      "id": "build_plan",
      "prompt": "What will you build across the two days?",
      "kind": "long",
      "required": true,
      "why": "Scope it to about 23 hours of floor time: doors 9:00 AM, building cleared 8:30 PM, both days. There is no overnight."
    },
    {
      "id": "shipped_before",
      "prompt": "Link one thing you shipped that someone other than you has used.",
      "kind": "short",
      "required": false,
      "why": "The strongest signal in this lane. Optional because a first-timer with a real plan is still worth a seat."
    },
    {
      "id": "team_status",
      "prompt": "Looking for teammates? What skills?",
      "kind": "long",
      "required": false
    }
  ],
  "decided_by": "event_admin_or_organizer",
  "grants_roles": [
    "participant"
  ],
  "consumes_seat": true
}

